 "content": "from collections import Counter


def transform(grid):
    """Complete the partial stripe by filling its background half with 1."""
    if not grid:
        return []
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    full_stripes = {row[0] for row in grid if row and len(set(row)) == 1 and row[0] != bg}
    for i, row in enumerate(grid):
        colors = set(row) - {bg}
        if len(colors) == 1:
            color = next(iter(colors))
            if color in full_stripes:
                out[i] = [1 if v == bg else v for v in row]
    return out
